 78	  <h1>Todos</h1>
 79	  <form id="todo-form" autocomplete="off">
 80	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo">
 81	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
 82	    <select data-testid="todo-priority" aria-label="Priority">
 83	      <option value="low">Low</option>
 84	      <option value="med" selected>Med</option>
 85	      <option value="high">High</option>
 86	    </select>
 87	    <button data-testid="todo-add" class="add" type="submit">Add</button>
 88	  </form>
 89	  <div class="filters" role="group" aria-label="Filter todos">
 90	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
 91	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
 92	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
 93	  </div>
 94	  <ul data-testid="todo-list"></ul>
 95	  <p class="empty" hidden>No todos yet.</p>
 96	</main>
 97	<script>
 98	(function () {
 99	  var STORAGE_KEY = 'todos';
100	  var form = document.getElementById('todo-form');
101	  var input = document.querySelector('[data-testid="todo-input"]');
102	  var dueInput = document.querySelector('[data-testid="todo-due"]');
103	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
104	  var list = document.querySelector('[data-testid="todo-list"]');
105	  var empty = document.querySelector('.empty');
106	  var filterButtons = document.querySelectorAll('[data-filter]');
107	  var filter = 'all';
108	
109	  function load() {
110	    try {
111	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
112	      if (!Array.isArray(data)) return [];
113	      return data.filter(function (t) {
114	        return t && typeof t.id === 'string' && typeof t.text === 'string';
115	      }).map(function (t) {
116	        t.completed = t.completed === true;
117	        t.due = isDateString(t.due) ? t.due : null;
118	        t.priority = isPriority(t.priority) ? t.priority : DEFAULT_PRIORITY;
119	        return t;
120	      });
121	    } catch (e) {
122	      return [];
123	    }
124	  }
125	
126	  function save() {
127	    try {
128	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
129	    } catch (e) {
130	      // Storage unavailable or full; keep working in memory.
131	    }
132	  }
133	
134	  var PRIORITIES = ['low', 'med', 'high'];
135	  var DEFAULT_PRIORITY = 'med';
136	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
137	
138	  function isPriority(value) {
139	    return PRIORITIES.indexOf(value) !== -1;
140	  }
141	
142	  function makeId() {
143	    if (window.crypto && typeof crypto.randomUUID === 'function') {
144	      try { return crypto.randomUUID(); } catch (e) { /* fall through */ }
145	    }
146	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
147	  }
148	
149	  // Due date rule (project decision): `due` is a plain 'YYYY-MM-DD' string
150	  // holding a LOCAL calendar date, or null. Never parse it with `new Date(str)`
151	  // (that reads it as UTC midnight). Overdue means due < today's local date,
152	  // compared as strings; a todo due today is never overdue.
153	  function isDateString(value) {
154	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value);
155	  }
156	
157	  function pad(n) {
158	    return (n < 10 ? '0' : '') + n;
159	  }
160	
161	  function todayLocal() {
162	    var d = new Date();
163	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
164	  }
165	
166	  function isOverdue(todo, today) {
167	    return todo.due !== null && todo.due < today;
168	  }
169	
170	  function formatDue(due) {
171	    var parts = due.split('-');
172	    var local = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
173	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
174	  }
175	
176	  // Ordering rule (project decision): completed todos always sit below all
177	  // active todos. Within each group, higher priority comes first
178	  // (high, med, low); equal priority keeps insertion order, oldest first.
179	  // `todos` is stored in insertion order and never reordered.
180	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
181	
182	  function ordered() {
183	    return todos.map(function (t, i) { return { todo: t, index: i }; })
184	      .sort(function (a, b) {
185	        return (a.todo.completed - b.todo.completed) ||
186	          (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) ||
187	          (a.index - b.index);
188	      })
189	      .map(function (entry) { return entry.todo; });
190	  }
191	
192	  function visible(todo) {
193	    if (filter === 'active') return !todo.completed;
194	    if (filter === 'completed') return todo.completed;
195	    return true;
196	  }
197	
198	  function render() {
199	    list.textContent = '';
200	    var shown = ordered().filter(visible);
201	    var today = todayLocal();
202	    renderedDay = today;
203	    shown.forEach(function (todo) {
204	      var li = document.createElement('li');
205	      li.setAttribute('data-testid', 'todo-item');
206	      li.setAttribute('data-id', todo.id);
207	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
208	      li.setAttribute('data-priority', todo.priority);
209	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
210	
211	      var box = document.createElement('input');
212	      box.type = 'checkbox';
213	      box.className = 'toggle';
214	      box.setAttribute('data-testid', 'todo-toggle');
215	      box.setAttribute('aria-label', 'Mark "' + todo.text + '" complete');
216	      box.checked = todo.completed;
217	      box.addEventListener('change', function () { toggle(todo.id); });
218	
219	      var span = document.createElement('span');
220	      span.className = 'text';
221	      span.setAttribute('data-testid', 'todo-text');
222	      span.textContent = todo.text;
223	
224	      var del = document.createElement('button');
225	      del.type = 'button';
226	      del.className = 'delete';
227	      del.setAttribute('data-testid', 'todo-delete');
228	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
229	      del.textContent = 'Delete';
230	      del.addEventListener('click', function () { remove(todo.id); });
231	
232	      li.appendChild(box);
233	      var priority = document.createElement('span');
234	      priority.className = 'priority';
235	      priority.textContent = PRIORITY_LABELS[todo.priority];
236	
237	      li.appendChild(span);
238	      li.appendChild(priority);
239	      if (todo.due) {
240	        var due = document.createElement('time');
241	        due.className = 'due';
242	        due.setAttribute('data-testid', 'todo-due-date');
243	        due.setAttribute('datetime', todo.due);
244	        due.textContent = (isOverdue(todo, today) ? 'Overdue: ' : 'Due ') + formatDue(todo.due);
245	        li.appendChild(due);
246	      }
247	      li.appendChild(del);
248	      list.appendChild(li);
249	    });
250	    if (todos.length === 0) {
251	      empty.textContent = 'No todos yet.';
252	    } else if (filter === 'active') {
253	      empty.textContent = 'No active todos.';
254	    } else {
255	      empty.textContent = 'No completed todos.';
256	    }
257	    empty.hidden = shown.length > 0;
258	
259	    filterButtons.forEach(function (btn) {
260	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
261	    });
262	  }
263	
264	  function add(text, due, priority) {
265	    text = text.trim();
266	    if (!text) return false;
267	    todos.push({
268	      id: makeId(),
269	      text: text,
270	      completed: false,
271	      due: isDateString(due) ? due : null,
272	      priority: isPriority(priority) ? priority : DEFAULT_PRIORITY,
273	      createdAt: Date.now()
274	    });
275	    save();
276	    render();
277	    return true;
278	  }
279	
280	  function remove(id) {
281	    todos = todos.filter(function (t) { return t.id !== id; });
282	    save();
283	    render();
284	  }
285	
286	  function toggle(id) {
287	    todos.forEach(function (t) {
288	      if (t.id === id) t.completed = !t.completed;
289	    });
290	    save();
291	    render();
292	  }
293	
294	  var todos = load();
295	  var renderedDay = null;
296	
297	  // Re-render when the local date rolls over so overdue flags stay current.
298	  function refreshIfNewDay() {
299	    if (todayLocal() !== renderedDay) render();
300	  }
301	  setInterval(refreshIfNewDay, 60 * 1000);
302	  document.addEventListener('visibilitychange', function () {
303	    if (!document.hidden) refreshIfNewDay();
304	  });
305	
306	  filterButtons.forEach(function (btn) {
307	    btn.addEventListener('click', function () {
308	      filter = btn.getAttribute('data-filter');
309	      render();
310	    });
311	  });
312	
313	  form.addEventListener('submit', function (e) {
314	    e.preventDefault();
315	    if (add(input.value, dueInput.value, priorityInput.value)) {
316	      dueInput.value = '';
317	      priorityInput.value = DEFAULT_PRIORITY;
318	    }
319	    input.value = '';
320	    input.focus();
321	  });
322	
323	  render();
324	})();
325	</script>
326	</body>
327	</html>

