193	    if (filter === 'active') return !todo.completed;
194	    if (filter === 'completed') return todo.completed;
195	    return true;
196	  }
197	
198	  function render() {
199	    list.textContent = '';
200	    var shown = ordered().filter(visible);
201	    var today = todayLocal();
202	    renderedDay = today;
203	    shown.forEach(function (todo) {
204	      var li = document.createElement('li');
205	      li.setAttribute('data-testid', 'todo-item');
206	      li.setAttribute('data-id', todo.id);
207	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
208	      li.setAttribute('data-priority', todo.priority);
209	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
210	
211	      var box = document.createElement('input');
212	      box.type = 'checkbox';
213	      box.className = 'toggle';
214	      box.setAttribute('data-testid', 'todo-toggle');
215	      box.setAttribute('aria-label', 'Mark "' + todo.text + '" complete');
216	      box.checked = todo.completed;
217	      box.addEventListener('change', function () { toggle(todo.id); });
218	
219	      var span = document.createElement('span');
220	      span.className = 'text';
221	      span.setAttribute('data-testid', 'todo-text');
222	      span.textContent = todo.text;
223	
224	      var del = document.createElement('button');
225	      del.type = 'button';
226	      del.className = 'delete';
227	      del.setAttribute('data-testid', 'todo-delete');
228	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
229	      del.textContent = 'Delete';
230	      del.addEventListener('click', function () { remove(todo.id); });
231	
232	      li.appendChild(box);
233	      var priority = document.createElement('span');
234	      priority.className = 'priority';
235	      priority.textContent = PRIORITY_LABELS[todo.priority];
236	
237	      li.appendChild(span);
238	      li.appendChild(priority);
239	      if (todo.due) {
240	        var due = document.createElement('time');
241	        due.className = 'due';
242	        due.setAttribute('data-testid', 'todo-due-date');
243	        due.setAttribute('datetime', todo.due);
244	        due.textContent = (isOverdue(todo, today) ? 'Overdue: ' : 'Due ') + formatDue(todo.due);
245	        li.appendChild(due);
246	      }
247	      li.appendChild(del);
248	      list.appendChild(li);
249	    });
250	    if (todos.length === 0) {
251	      empty.textContent = 'No todos yet.';
252	    } else if (filter === 'active') {
253	      empty.textContent = 'No active todos.';
254	    } else {
255	      empty.textContent = 'No completed todos.';
256	    }
257	    empty.hidden = shown.length > 0;
258	
259	    filterButtons.forEach(function (btn) {
260	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
261	    });
262	  }
263	
264	  function add(text, due, priority) {
265	    text = text.trim();
266	    if (!text) return false;
267	    todos.push({
268	      id: makeId(),
269	      text: text,
270	      completed: false,
271	      due: isDateString(due) ? due : null,
272	      priority: isPriority(priority) ? priority : DEFAULT_PRIORITY,
273	      createdAt: Date.now()
274	    });
275	    save();
276	    render();
277	    return true;
278	  }
279	
280	  function remove(id) {
281	    todos = todos.filter(function (t) { return t.id !== id; });
282	    save();
283	    render();
284	  }
285	
286	  function toggle(id) {
287	    todos.forEach(function (t) {
288	      if (t.id === id) t.completed = !t.completed;
289	    });
290	    save();
291	    render();
292	  }
293	
294	  var todos = load();
295	  var renderedDay = null;
296	
297	  // Re-render when the local date rolls over so overdue flags stay current.
298	  function refreshIfNewDay() {
299	    if (todayLocal() !== renderedDay) render();
300	  }
301	  setInterval(refreshIfNewDay, 60 * 1000);
302	  document.addEventListener('visibilitychange', function () {
303	    if (!document.hidden) refreshIfNewDay();
304	  });
305	
306	  filterButtons.forEach(function (btn) {
307	    btn.addEventListener('click', function () {
308	      filter = btn.getAttribute('data-filter');
309	      render();
310	    });
311	  });
312	
313	  form.addEventListener('submit', function (e) {
314	    e.preventDefault();
315	    if (add(input.value, dueInput.value, priorityInput.value)) {
316	      dueInput.value = '';
317	      priorityInput.value = DEFAULT_PRIORITY;
318	    }
319	    input.value = '';
320	    input.focus();
321	  });
322	
323	  render();
324	})();
325	</script>
326	</body>
327	</html>

